@php
    $f = fn (int $v): string => number_format($v / 100, 2, ',', '.');
    $currency = $invoice->currencySymbol();
    $vat = ($company->is_vat_obligor ?? true) || $invoice->tax_total > 0;
    $kind = $template->value;
    $theme = match ($kind) {
        'terminal-matrix' => ['#15803d', '#f0fdf4', '[●]', 'matrix'],
        'programmer-catalog' => ['#1d4ed8', '#eff6ff', '[■]', 'catalog'],
        'editor-margin' => ['#7c3aed', '#faf5ff', '[◆]', 'editor'],
        'signal-plot' => ['#db2777', '#fdf2f8', '[◇]', 'signal'],
        default => ['#0f766e', '#f0fdfa', '[▲]', 'board'],
    };
@endphp
<!doctype html><html lang="sr"><head><meta charset="utf-8"><title>Račun {{ $invoice->invoice_number }}</title><style>@page{margin:0}*{box-sizing:border-box}body{margin:0;color:#172033;font-family:DejaVu Sans,sans-serif;font-size:8pt}.p{padding:14mm 16mm 18mm}.mono{font-family:DejaVu Sans Mono,monospace}.accent{color:{{ $theme[0] }}}.head{padding:9mm;background:{{ $theme[1] }};border-top:5px solid {{ $theme[0] }};}.head table,.data,.items,.sum{width:100%;border-collapse:collapse}.head td{vertical-align:top}.brand{font-size:18pt;font-weight:bold}.no{text-align:right;font-size:19pt;font-weight:bold}.muted{color:#64748b;line-height:1.5}.data{margin:8mm 0}.data td{width:50%;padding:7px;vertical-align:top;border:1px solid #dbe4ea}.data td+td{border-left:0}.client{font-size:10pt;font-weight:bold}.items th{padding:7px 4px;background:{{ $theme[0] }};color:#fff;font-size:6pt;text-align:left}.items td{padding:7px 4px;border-bottom:1px solid #dbe4ea;vertical-align:top}.r{text-align:right;white-space:nowrap}.c{text-align:center}.sum{width:44%;margin:8mm 0 0 auto;border:1px solid {{ $theme[0] }};}.sum td{padding:6px 8px;border-top:1px solid #dbe4ea}.sum td:last-child{text-align:right;font-weight:bold}.total td{background:{{ $theme[0] }};color:#fff;font-size:11pt}.box{margin-top:7mm;padding:8px;border-left:3px solid {{ $theme[0] }};background:{{ $theme[1] }};white-space:pre-line}.matrix .head{background-image:radial-gradient({{ $theme[0] }} 1px,transparent 1px);background-size:7px 7px}.catalog .head{border-left:18mm solid {{ $theme[0] }};background:#fff}.editor .head{border-left:5mm solid {{ $theme[0] }};border-top:0}.signal .head{border-radius:0 0 18mm 0}.board .data td:first-child{background:{{ $theme[1] }}}.foot{position:fixed;bottom:7mm;left:16mm;color:#94a3b8;font-size:6pt}</style></head><body><div class="p {{ $theme[3] }}"><div class="head"><table><tr><td><div class="accent mono">{{ $theme[2] }}</div><div class="brand">{{ $company->name }}</div><div class="muted">{{ $company->address }}<br>{{ $company->zip }} {{ $company->city }}</div></td><td class="no accent mono">{{ $invoice->invoice_number }}<br><span class="muted" style="font-size:7pt">{{ $invoice->date?->format('d.m.Y.') }}</span></td></tr></table></div><table class="data"><tr><td><div class="accent mono">KUPAC</div><div class="client">{{ $invoice->client?->name ?? '—' }}</div><div class="muted">{{ $invoice->client?->address }}<br>{{ $invoice->client?->zip }} {{ $invoice->client?->city }}</div></td><td><div class="accent mono">PARAMETRI</div><div class="muted">Rok: <strong>{{ $invoice->due_date?->format('d.m.Y.') ?? '—' }}</strong><br>Plaćanje: <strong>{{ $invoice->payment_type?->label() ?? '—' }}</strong><br>Valuta: <strong>{{ $invoice->currency }}</strong></div></td></tr></table><table class="items"><thead><tr><th>#</th><th style="width:43%">STAVKA</th><th class="c">JM</th><th class="r">KOL.</th><th class="r">CIJENA</th>@if($vat)<th class="r">PDV</th>@endif<th class="r">IZNOS</th></tr></thead><tbody>@foreach($invoice->items as $i=>$item) @php($q=max(1,(int)$item->quantity))<tr><td>{{ $i+1 }}</td><td><strong>{{ $item->name }}</strong></td><td class="c">{{ $item->unit?->value }}</td><td class="r">{{ $item->quantity }}</td><td class="r">{{ $f((int)round($item->total/$q)) }} {{ $currency }}</td>@if($vat)<td class="r">{{ number_format($item->tax_rate/100,2,',','.') }}%</td>@endif<td class="r"><strong>{{ $f($item->total) }} {{ $currency }}</strong></td></tr>@endforeach</tbody></table><table class="sum"><tr><td>Osnovica</td><td>{{ $f($invoice->subtotal) }} {{ $currency }}</td></tr>@if($vat)<tr><td>PDV</td><td>{{ $f($invoice->tax_total) }} {{ $currency }}</td></tr>@endif<tr class="total"><td>UKUPNO</td><td>{{ $f($invoice->total) }} {{ $currency }}</td></tr></table>@if($invoice->notes)<div class="box">{{ $invoice->notes }}</div>@endif</div><div class="foot mono">{{ $theme[2] }} / {{ $invoice->invoice_number }}</div></body></html>
